BEGIN;
SELECT no_plan();
SELECT is((SELECT active_provider FROM payment_runtime_config WHERE id),'none','Migration blocks new payments by default');
SET LOCAL ROLE anon;
SELECT throws_ok('SELECT * FROM public.payment_runtime_config','42501',NULL,'anon cannot read config');
SELECT throws_ok('UPDATE public.payment_runtime_config SET active_provider=''square''','42501',NULL,'anon cannot update config');
SELECT throws_ok('SELECT * FROM public.payment_processor_audit','42501',NULL,'anon cannot read audit');
SELECT throws_ok('SELECT public.set_payment_runtime_provider(''00000000-0000-4000-8000-000000000001'',''square'',0,NULL)','42501',NULL,'anon cannot switch');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT throws_ok('SELECT * FROM public.payment_runtime_config','42501',NULL,'authenticated cannot read config');
SELECT throws_ok('INSERT INTO public.payment_runtime_config(id) VALUES(true)','42501',NULL,'authenticated cannot insert config');
SELECT throws_ok('UPDATE public.payment_runtime_config SET active_provider=''paypal''','42501',NULL,'authenticated cannot update config');
SELECT throws_ok('DELETE FROM public.payment_runtime_config','42501',NULL,'authenticated cannot delete config');
SELECT throws_ok('SELECT public.set_payment_runtime_provider(''00000000-0000-4000-8000-000000000001'',''square'',0,NULL)','42501',NULL,'even authenticated admin cannot bypass edge gates');
SELECT throws_ok('INSERT INTO public.payment_processor_audit(actor_user_id,old_provider,new_provider) VALUES(''00000000-0000-4000-8000-000000000001'',''none'',''square'')','42501',NULL,'cannot forge audit');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT throws_ok('SELECT public.set_payment_runtime_provider(''00000000-0000-4000-8000-000000000002'',''square'',0,NULL)','42501',NULL,'SQL rechecks admin');
SELECT lives_ok('SELECT public.set_payment_runtime_provider(''00000000-0000-4000-8000-000000000001'',''square'',0,''First activation'')','service admin activates square');
SELECT lives_ok('SELECT public.set_payment_runtime_provider(''00000000-0000-4000-8000-000000000001'',''paypal'',1,''Switch'')','service admin switches paypal');
SELECT is((SELECT count(*)::integer FROM payment_processor_audit),2,'one audit per successful change');
SELECT is((SELECT old_provider FROM payment_processor_audit ORDER BY id DESC LIMIT 1),'square','audit old provider');
SELECT is((SELECT new_provider FROM payment_processor_audit ORDER BY id DESC LIMIT 1),'paypal','audit new provider');
SELECT is((SELECT actor_user_id::text FROM payment_processor_audit ORDER BY id DESC LIMIT 1),'00000000-0000-4000-8000-000000000001','audit actor');
SELECT ok((SELECT changed_at IS NOT NULL AND reason='Switch' FROM payment_processor_audit ORDER BY id DESC LIMIT 1),'audit timestamp and reason');
SELECT throws_ok('SELECT public.set_payment_runtime_provider(''00000000-0000-4000-8000-000000000001'',''square'',0,NULL)','P0001',NULL,'stale update rejected');
SELECT throws_ok('SELECT public.set_payment_runtime_provider(''00000000-0000-4000-8000-000000000001'',''clover'',2,NULL)','P0001',NULL,'unsupported processor rejected');
SELECT throws_ok('SELECT public.set_payment_runtime_provider(''00000000-0000-4000-8000-000000000001'',''none'',2,repeat(''x'',501))','23514',NULL,'audit failure rolls back config');
SELECT is((SELECT active_provider FROM payment_runtime_config WHERE id),'paypal','failed changes preserve selection');
SELECT is((SELECT version FROM payment_runtime_config WHERE id),2,'failed changes preserve version');
SELECT is((SELECT count(*)::integer FROM payment_processor_audit),2,'failed changes create no audit');
SELECT lives_ok('SELECT public.set_payment_runtime_provider(''00000000-0000-4000-8000-000000000001'',''none'',2,NULL)','explicit stop');
SELECT is((SELECT active_provider FROM payment_runtime_config WHERE id),'none','explicit stop persists');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
